mapper.select:

WHERE iv.batch_id = #{batchId}
  AND iv.lab_id = (SELECT lab_id FROM mentor WHERE id = #{mentorId})
ORDER BY iv.scheduled_at, iv.id

mapper.update:
UPDATE interview
SET scheduled_at = #{scheduledAt}, location = #{location}, score = #{score},
    comment = #{comment}, conclusion = #{conclusion}, status = #{status},
    mentor_id = #{mentorId}, recorded_by = #{recordedBy}, recorded_at = #{recordedAt}
WHERE id = #{id}
